parts.openscad_module:
$fn = 96;

nema_face_size     = 42.3;
nema_bolt_circle   = 31;
nema_shaft_boss_d  = 22;
nema_bolt_hole_d   = 3.4;
plate_size         = 60;
plate_thickness    = 5;
edge_margin        = (plate_size - nema_face_size) / 2;

module nema17_motor_mount() {
  difference() {
    cube([plate_size, plate_size, plate_thickness], center = true);
    cylinder(h = plate_thickness + 2, d = nema_shaft_boss_d, center = true, $fn = 64);
    for (x = [-nema_bolt_circle/2, nema_bolt_circle/2])
      for (y = [-nema_bolt_circle/2, nema_bolt_circle/2])
        translate([x, y, 0])
          cylinder(h = plate_thickness + 2, d = nema_bolt_hole_d, center = true, $fn = 32);
  }
}

nema17_motor_mount();

$fn = 96;

leg_a           = 50;
leg_b           = 50;
leg_width       = 30;
plate_thickness = 4;
hole_d          = 5.5;
edge_margin     = 8;

module slot_cut(len, d, h) {
  hull() {
    translate([-len/2 + d/2, 0, 0]) cylinder(h = h, d = d, center = true, $fn = 32);
    translate([ len/2 - d/2, 0, 0]) cylinder(h = h, d = d, center = true, $fn = 32);
  }
}

module l_bracket() {
  difference() {
    union() {
      cube([leg_a, leg_width, plate_thickness], center = true);
      translate([-leg_a/2 + plate_thickness/2, 0, leg_b/2])
        cube([plate_thickness, leg_width, leg_b], center = true);
      translate([-leg_a/2 + plate_thickness, 0, plate_thickness/2])
        rotate([0, 45, 0])
          cube([plate_thickness * 1.4, leg_width, plate_thickness * 1.4], center = true);
    }
    for (x = [leg_a/4, -leg_a/4])
      translate([x, 0, 0])
        cylinder(h = plate_thickness + 2, d = hole_d, center = true, $fn = 32);
    translate([-leg_a/2 + plate_thickness/2, 0, leg_b * 0.35])
      rotate([0, 90, 0])
        cylinder(h = plate_thickness + 2, d = hole_d, center = true, $fn = 32);
  }
}

l_bracket();
